package api

var sswCurriculumWoodIndustryEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.title", source: `Penerimaan kayu dan pencocokan identitas`}:                                                                                                     `Wood Receiving and Identity Checks`,
	{field: "ssw.title", source: `Sifat kayu, arah serat, dan cacat terlihat`}:                                                                                                   `Wood Properties, Grain Direction, and Visible Defects`,
	{field: "ssw.title", source: `Kadar air, pengeringan, dan penyimpanan kayu`}:                                                                                                 `Moisture Content, Drying, and Wood Storage`,
	{field: "ssw.title", source: `Penggergajian dan instruksi ukuran`}:                                                                                                           `Sawing and Size Instructions`,
	{field: "ssw.title", source: `Produk panel: venir, kayu lapis, dan kayu laminasi`}:                                                                                           `Panel Products: Veneer, Plywood, and Laminated Wood`,
	{field: "ssw.title", source: `Pengukuran dimensi dan pemeriksaan sampel`}:                                                                                                    `Dimension Measurement and Sample Inspection`,
	{field: "ssw.title", source: `Permukaan, tepi, dan cacat pemrosesan`}:                                                                                                        `Surfaces, Edges, and Processing Defects`,
	{field: "ssw.title", source: `Label mutu, kelompok produk, dan ketertelusuran`}:                                                                                              `Quality Labels, Product Lots, and Traceability`,
	{field: "ssw.title", source: `Penumpukan dan kestabilan bundel`}:                                                                                                             `Stacking and Bundle Stability`,
	{field: "ssw.title", source: `Pengemasan dan pemeriksaan tujuan`}:                                                                                                            `Packaging and Destination Checks`,
	{field: "ssw.title", source: `Pembersihan, perawatan rutin, dan laporan giliran`}:                                                                                            `Cleaning, Routine Maintenance, and Shift Reports`,
	{field: "ssw.description", source: `Mengenali asal, jenis, sifat, kondisi, dan identitas bahan kayu sebelum bahan masuk ke lini produksi.`}:                                  `Identify the source, type, properties, condition, and identity of wood materials before they enter the production line.`,
	{field: "ssw.description", source: `Mengikuti instruksi pada lini penggergajian, pemotongan, venir, panel, atau produk kayu lain tanpa melewati pelindung dan batas tugas.`}: `Follow instructions on sawing, cutting, veneer, panel, and other wood-product lines without bypassing guards or assigned-duty limits.`,
	{field: "ssw.description", source: `Memeriksa dimensi, bentuk, permukaan, dan penandaan hasil sesuai kriteria produk sebelum dilepas ke tahap berikutnya.`}:                  `Check product dimensions, shape, surface, and markings against product criteria before releasing it to the next stage.`,
	{field: "ssw.description", source: `Menjaga hasil kayu tetap stabil dan beridentitas selama disimpan, dipindahkan, atau diserahkan ke proses berikutnya.`}:                   `Keep wood products stable and identifiable during storage, transfer, and handover to the next process.`,
	{field: "ssw.objective", source: `Mencocokkan tanda petak atau pemasok, jenis bahan, jumlah, dan kondisi kayu dengan dokumen penerimaan.`}:                                   `Match plot or supplier markings, material type, quantity, and wood condition to the receiving documents.`,
	{field: "ssw.objective", source: `Mengenali serat, mata kayu, retak, perubahan bentuk, dan kondisi lain yang memengaruhi pemakaian bahan.`}:                                  `Identify grain, knots, cracks, deformation, and other conditions that affect material use.`,
	{field: "ssw.objective", source: `Membaca target kadar air atau kondisi pengeringan yang diberikan dan menyimpan kayu agar tidak berubah bentuk.`}:                           `Read the specified moisture target or drying condition and store wood to prevent deformation.`,
	{field: "ssw.objective", source: `Memeriksa pelindung, tombol berhenti, area lintasan, serta kondisi mesin sebelum menjalankan alat sesuai tugas.`}:                          `Check guards, stop buttons, travel areas, and machine condition before operating equipment within your assigned duties.`,
	{field: "ssw.objective", source: `Mencocokkan bahan serta instruksi ukuran sebelum pemotongan dan menghentikan proses bila data tidak jelas.`}:                               `Match the material and size instructions before cutting, and stop if any information is unclear.`,
	{field: "ssw.objective", source: `Mengenali alur umum bahan panel dan mengikuti identitas, urutan, serta petunjuk kerja pada produk yang dibuat.`}:                           `Recognize the general flow of panel materials and follow the identity, sequence, and work instructions for the product being made.`,
	{field: "ssw.objective", source: `Mengukur produk dengan alat serta titik ukur yang ditentukan dan mencatat hasil aktual.`}:                                                  `Measure products with the specified tool and at designated points, and record the actual results.`,
	{field: "ssw.objective", source: `Mengenali serpihan, retak, permukaan kasar, atau cacat hasil proses serta memisahkannya sesuai kriteria.`}:                                 `Identify splinters, cracks, rough surfaces, and processing defects, and separate items according to criteria.`,
	{field: "ssw.objective", source: `Memastikan tanda produk, spesifikasi, grade yang telah ditetapkan, dan jumlah cocok sebelum hasil dipindahkan.`}:                           `Confirm that product markings, specifications, assigned grade, and quantity match before moving the output.`,
	{field: "ssw.objective", source: `Menyusun kayu sesuai batas tumpukan dan menggunakan penyangga serta area simpan yang ditetapkan.`}:                                         `Stack wood within the specified height limits and use designated supports and storage areas.`,
	{field: "ssw.objective", source: `Mencocokkan jumlah, ukuran, label pelanggan, dan kondisi ikatan sebelum kayu dikirim.`}:                                                    `Check quantity, dimensions, customer labels, and bundle ties before shipping the wood.`,
	{field: "ssw.objective", source: `Membersihkan area sesuai tugas, melaporkan keausan alat atau kebocoran, dan menyerahkan status mesin serta lot.`}:                          `Clean the area within your duties, report worn equipment or leaks, and hand over machine and lot status.`,
}

